mapper.select:
SELECT t.conversation_id, t.trace_id, t.user_id, t.source,
       t.agent_id, t.agent_name, t.start_ts, t.end_ts,
       t.duration_ms, t.status, t.error_message,
       t.event_count, t.token_input, t.token_output, t.model, t.environment
FROM (
    SELECT * FROM trace_conversation

    AND environment = #{environment}

            AND source = #{source}


            AND user_id = #{userId}

        AND (conversation_id LIKE concat('%', #{keyword}, '%') OR user_id LIKE concat('%', #{keyword}, '%') OR agent_name LIKE concat('%', #{keyword}, '%'))

    ORDER BY end_ts DESC, trace_id DESC, start_ts DESC
    LIMIT 1 BY conversation_id
) AS t
ORDER BY t.start_ts DESC, t.conversation_id
LIMIT #{offset}, #{limit}

SELECT count(DISTINCT conversation_id)
FROM trace_conversation

    AND environment = #{environment}

        AND source = #{source}


        AND user_id = #{userId}

    AND (conversation_id LIKE concat('%', #{keyword}, '%') OR user_id LIKE concat('%', #{keyword}, '%') OR agent_name LIKE concat('%', #{keyword}, '%'))
